import {MatLegacyErrorHarness} from "../../projects/ngx-material-legacy/legacy-form-field/testing/error-harness";
export class DerivedErrorHarness extends MatLegacyErrorHarness {
  static inheritedPredicate() {
    return super._getErrorPredicate(DerivedErrorHarness, {text: 'Required'});
  }
}

import {MatLegacyErrorHarness} from '../../projects/ngx-material-legacy/legacy-form-field/testing/error-harness';
import {MatErrorHarness, ErrorHarnessFilters} from '@angular/material/form-field/testing';
import {ComponentHarnessConstructor} from '@angular/cdk/testing';
export class ExposedErrorHarness extends MatLegacyErrorHarness {
  static forType<T extends MatErrorHarness>(type: ComponentHarnessConstructor<T>, options: ErrorHarnessFilters) {
    return this._getErrorPredicate(type, options);
  }
}
export const legacy = ExposedErrorHarness.forType(MatLegacyErrorHarness, {});
export const modern = ExposedErrorHarness.forType(MatErrorHarness, {});
export const derived = ExposedErrorHarness.forType(ExposedErrorHarness, {});

import {MatLegacyErrorHarness} from "../../projects/ngx-material-legacy/legacy-form-field/testing/error-harness";
export class DerivedErrorHarness extends MatLegacyErrorHarness {
  static inheritedPredicate() {
    return super._getErrorPredicate(DerivedErrorHarness, {text: 'Required'});
  }
}
